#!/bin/sh
# Generate .env.lakehouse with random local secrets. Never overwrites an existing file.
set -eu
f=.env.lakehouse
if [ -f "$f" ]; then echo "$f exists; leaving it unchanged"; exit 0; fi
rand() { python3 -c 'import secrets; print(secrets.token_urlsafe(24))'; }
umask 077
cat > "$f" <<EOF
# Milestone 3 lakehouse secrets. Generated by scripts/make-lakehouse-env.sh. Git-ignored.
LAKEHOUSE_CATALOG_PASSWORD=$(rand)
# Garage formats: key id GK + 24 hex, secret and RPC secret 64 hex.
LAKEHOUSE_S3_ACCESS_KEY=GK$(python3 -c 'import secrets; print(secrets.token_hex(12))')
LAKEHOUSE_S3_SECRET_KEY=$(python3 -c 'import secrets; print(secrets.token_hex(32))')
GARAGE_RPC_SECRET=$(python3 -c 'import secrets; print(secrets.token_hex(32))')
GARAGE_ADMIN_TOKEN=$(rand)
EOF
echo "wrote $f (mode 600)"
